class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def check(T: int) -> bool:
            if T <= 0:
                return True
            moves = 0
            carry = 0  # visits already given to current index from prior oscillation
            for i in range(n):
                f_i = (T + points[i] - 1) // points[i]  # ceil(T / points[i])
                if i == n - 1:
